/**
 * Receives the status webhook of a launched agent and fires its stop watch
 * now, so the watch reads the stopped run and wakes its conversation once.
 * A webhook for an agent with no armed watch (already woken, cancelled, or
 * never watched) does nothing. A launch whose reply was lost leaves a pending
 * claim on the agent; the webhook turns it into a launch, so the woken
 * conversation can read the agent.
 */
import * as z from "zod/v4";
import { defineChannel, hmacSignatureAuth, POST } from "../../../channels.js";
import { PLATFORM_WEBHOOK_SECRET_NAME } from "../../../internal/hosting.js";
import { adoptPendingLaunch } from "../lib/fleet.js";
import { saveStopSignal } from "../lib/stop-signal.js";
import { fireWatches } from "../lib/watch.js";
/** Signature header and prefix of the Cloud Agents status webhook. */
const STOP_WEBHOOK_SIGNATURE = { header: "X-Webhook-Signature", prefix: "sha256=" };
const channel = defineChannel({
    auth: [hmacSignatureAuth({ ...STOP_WEBHOOK_SIGNATURE, secret: PLATFORM_WEBHOOK_SECRET_NAME })],
    routes: [
        POST("/", {
            description: "Cloud Agents status webhook: fires the stop watch of the agent it names.",
            bodySchema: z.object({
                id: z.string().min(1),
                status: z.string().optional(),
                timestamp: z.string().optional(),
            }),
            handler: async (_request, args) => {
                const { id, status, timestamp } = args.body;
                // Before the fire, so the turn it wakes can read the agent with cloud__get.
                await adoptPendingLaunch(args.host.kv, id);
                // Saved before the fire, so the watch need not read a status that may lag.
                if (status !== undefined && timestamp !== undefined) {
                    await saveStopSignal(args.host.kv, id, { status, timestamp });
                }
                const reminders = args.host.reminders;
                const fired = reminders === undefined ? 0 : await fireWatches(reminders, id);
                return Response.json({ fired });
            },
        }),
    ],
});
export default channel;
